import React, { useState, useEffect, useRef } from 'react';
import { ShoppingBag, Moon, Sun, Menu, X } from 'lucide-react';
import * as THREE from 'three';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';

export default function AreaBoyz() {
  const [isDark, setIsDark] = useState(true);
  const [cart, setCart] = useState([]);
  const [showCart, setShowCart] = useState(false);
  const [selectedProduct, setSelectedProduct] = useState(null);
  const [activeSection, setActiveSection] = useState(0);
  const [currentPage, setCurrentPage] = useState('home'); // 'home', 'products', 'about', 'product-detail', 'category-standard', 'category-3d', 'category-fitness', 'category-leg'
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [showMenu, setShowMenu] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState(null);

  // 3D Canvas refs
  const canvasRef = useRef(null);
  const rendererRef = useRef(null);
  const modelRef = useRef(null);

  // Cleanup body overflow on unmount
  useEffect(() => {
    return () => {
      if (typeof document !== 'undefined') document.body.style.overflow = 'auto';
    };
  }, []);

  const handleProductClick = (product) => {
    setSelectedProduct(product);
    setCurrentPage('product-detail');
    window.scrollTo(0, 0);
  };

  // Initialize 3D Scene
  useEffect(() => {
    if (!canvasRef.current) return;

    canvasRef.current.innerHTML = '';

    const width = window.innerWidth;
    const height = window.innerHeight;

    const scene = new THREE.Scene();

    const camera = new THREE.PerspectiveCamera(75, width / height, 0.1, 1000);
    camera.position.z = 3.5;
    camera.position.x = -1.2;
    camera.position.y = -0.3;

    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    renderer.setSize(width, height);
    renderer.setPixelRatio(window.devicePixelRatio);
    canvasRef.current.appendChild(renderer.domElement);
    rendererRef.current = renderer;

    // Lighting
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.8);
    scene.add(ambientLight);

    const directionalLight = new THREE.DirectionalLight(0xffffff, 1.5);
    directionalLight.position.set(10, 8, 10);
    scene.add(directionalLight);

    // Add a placeholder geometry while model loads
    const geometry = new THREE.CylinderGeometry(0.6, 0.6, 2, 32);
    const material = new THREE.MeshStandardMaterial({ color: 0x1a1a1a, metalness: 0.7, roughness: 0.2 });
    const placeholder = new THREE.Mesh(geometry, material);
    placeholder.position.x = -0.5;
    scene.add(placeholder);
    modelRef.current = placeholder;

    // Load Model with better error handling
    const loader = new GLTFLoader();
    const modelPath = process.env.PUBLIC_URL + '/green_arm_bracer_3d_model.glb';
    
    loader.load(
      modelPath,
      (gltf) => {
        console.log('✅ Model loaded successfully!');
        const model = gltf.scene;

        const box = new THREE.Box3().setFromObject(model);
        const size = box.getSize(new THREE.Vector3());
        const maxDim = Math.max(size.x, size.y, size.z);
        const scale = 5.5 / maxDim;
        model.scale.multiplyScalar(scale);

        box.setFromObject(model);
        const center = box.getCenter(new THREE.Vector3());
        model.position.x = -center.x;
        model.position.y = -center.y - 0.2;
        model.position.z = -center.z;

        model.rotation.x = 2;
        model.rotation.y = -1;
        model.rotation.z = 1;

        scene.remove(placeholder);
        scene.add(model);
        modelRef.current = model;
      },
      (progress) => {
        console.log('Loading model:', Math.round((progress.loaded / progress.total) * 100), '%');
      },
      (error) => {
        console.error('❌ Error loading model:', error);
        console.log('Tried to load from:', modelPath);
        console.log('Using placeholder instead');
      }
    );

    let rotationSpeed = 0.0015;

    const animate = () => {
      requestAnimationFrame(animate);

      if (modelRef.current) {
        modelRef.current.rotation.y += rotationSpeed;
      }

      renderer.render(scene, camera);
    };
    animate();

    const handleResize = () => {
      if (!canvasRef.current) return;
      const w = window.innerWidth;
      const h = window.innerHeight;
      camera.aspect = w / h;
      camera.updateProjectionMatrix();
      renderer.setSize(w, h);
    };

    window.addEventListener('resize', handleResize);

    return () => {
      window.removeEventListener('resize', handleResize);
      renderer.dispose();
    };
  }, []);

  const products = [
    { id: 1, name: 'Berserk Design', price: 89.99, colors: ['Black', 'Red'], image: 'berserk_design.png', category: 'standard' },
    { id: 2, name: 'Eagles Design', price: 75.99, colors: ['White', 'Red', 'Black'], image: 'eagles_design.png', category: 'standard' },
    { id: 3, name: 'Football Custom Design', price: 84.99, colors: ['Light Blue', 'Red', 'White'], image: 'football_custom_desgin.png', category: 'leg' },
    { id: 4, name: 'Standard Design', price: 54.99, colors: ['Gray'], image: 'standard_design.png', category: 'standard' },
    { id: 5, name: 'Zoro Design', price: 94.99, colors: ['Green', 'Red', 'Gold'], image: 'zoro_design.png', category: '3d' },
    { id: 6, name: 'Custom Design', price: 79.99, colors: ['Any'], category: 'fitness' }
  ];

  // Filter products based on selected category
  const filteredProducts = selectedCategory 
    ? products.filter(p => p.category === selectedCategory)
    : products;

  const menuCategories = {
    available: [
      { name: 'Standard Arm Sleeves', description: 'Premium arm sleeves for everyday wear' },
      { name: '3D Embroidered Fashion', description: 'Fashion-forward embroidered arm sleeves' },
      { name: 'Fitness Arm Sleeves with Zips', description: 'Full fitness sleeves with phone pockets & zips' },
      { name: 'Leg Stockings for Fitness', description: 'Football, Cricket & Athletic leg stockings' }
    ],
    comingSoon: [
      { name: 'Caps', description: 'Coming Soon' },
      { name: 'Gloves', description: 'Coming Soon' },
      { name: 'Women Accessories', description: 'Coming Soon' },
      { name: 'Men Accessories', description: 'Coming Soon' },
      { name: 'Wrist Bands', description: 'Coming Soon' },
      { name: 'Bandanas', description: 'Coming Soon' }
    ]
  };

  return (
    <div className={`${isDark ? 'bg-black text-white' : 'bg-white text-black'} transition-colors duration-500`}>
      <style jsx>{`
        @import url('https://fonts.googleapis.com/css2?family=Press+Start+2P&display=swap');
        
        * {
          font-family: 'Press Start 2P', cursive;
          -webkit-font-smoothing: antialiased;
        }

        /* Override Press Start for body text to make it readable */
        p, span:not(h1):not(h2):not(h3):not(h4):not(h5):not(h6) {
          font-family: 'Courier New', monospace;
          font-size: 0.9rem;
        }

        html {
          scroll-behavior: smooth;
        }

        body { scroll-behavior: smooth; }

        #canvas-container {
          position: fixed;
          top: 0;
          left: 0;
          width: 100%;
          height: 100%;
          z-index: 0;
          pointer-events: none;
        }

        #canvas-container canvas {
          width: 100% !important;
          height: 100% !important;
          display: block;
        }

        @keyframes float {
          0%, 100% { transform: translateY(0px); }
          50% { transform: translateY(-20px); }
        }

        @keyframes twinkle {
          0%, 100% { opacity: 0.3; }
          50% { opacity: 1; }
        }

        @keyframes slideUp {
          from {
            opacity: 0;
            transform: translateY(60px);
          }
          to {
            opacity: 1;
            transform: translateY(0);
          }
        }

        .section-appear {
          animation: slideUp 0.8s cubic-bezier(0.4, 0, 0.2, 1) forwards;
        }

        .accent-dot {
          position: absolute;
          border-radius: 50%;
          animation: float 6s ease-in-out infinite;
        }

        h1 { text-shadow: 0 4px 15px rgba(34, 197, 94, 0.4); }
        h2 { text-shadow: 0 4px 12px rgba(34, 197, 94, 0.3); }
        p { text-shadow: 0 2px 6px rgba(34, 197, 94, 0.2); }

        @media (max-width: 768px) {
          h1 { font-size: 2.5rem; }
          h2 { font-size: 1.875rem; }
          p { font-size: 0.875rem; }
        }
      `}</style>

      {/* Fixed Canvas Background - Only on Home */}
      <div id="canvas-container" ref={canvasRef} style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', zIndex: 0, pointerEvents: 'none', opacity: currentPage === 'home' ? 1 : 0, transition: 'opacity 0.6s ease', visibility: currentPage === 'home' ? 'visible' : 'hidden' }} />

      {/* Logo - Centered at Top - Only show on home, fixed position */}
      {currentPage === 'home' && (
        <div style={{ position: 'fixed', top: '20px', left: '50%', transform: 'translateX(-50%)', zIndex: 50, pointerEvents: 'auto' }}>
          <img 
            src={process.env.PUBLIC_URL + '/AB-removebg-preview.png'} 
            alt="AREA BOYZ Logo" 
            style={{
              width: '90px',
              height: '90px',
              objectFit: 'contain',
              filter: 'drop-shadow(0 0 8px rgba(34, 197, 94, 0.6))',
              transition: 'all 0.3s ease',
              cursor: 'pointer'
            }}
            onClick={() => setCurrentPage('home')}
            onError={(e) => {
              console.error('Logo failed to load');
              e.target.src = 'data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 100 100%22%3E%3Ctext x=%2250%22 y=%2270%22 font-size=%2260%22 font-weight=%22bold%22 text-anchor=%22middle%22 fill=%22%2322C55E%22%3EAB%3C/text%3E%3C/svg%3E';
            }}
          />
        </div>
      )}

      {/* Menu Modal - Clean Design */}
      {showMenu && (
        <>
          {/* Prevent body scroll */}
          {typeof document !== 'undefined' && (document.body.style.overflow = 'hidden')}
          <div className={`fixed inset-0 z-50 overflow-y-auto`} style={{ background: isDark ? 'linear-gradient(135deg, #0a0a0a 0%, #1a1a2a 100%)' : 'linear-gradient(135deg, #f9f9f9 0%, #efefef 100%)' }}>
            {/* Opaque background overlay */}
            <div style={{ position: 'fixed', inset: 0, background: isDark ? 'rgba(0, 0, 0, 1)' : 'rgba(255, 255, 255, 1)', zIndex: 0 }} />

            {/* Background Elements */}
            <div style={{ position: 'fixed', inset: 0, zIndex: 1, overflow: 'hidden', pointerEvents: 'none' }}>
              {[...Array(20)].map((_, i) => (
                <div
                  key={i}
                  style={{
                    position: 'absolute',
                    width: `${100 + Math.random() * 200}px`,
                    height: `${100 + Math.random() * 200}px`,
                    background: 'radial-gradient(circle, rgba(34, 197, 94, 0.05) 0%, transparent 70%)',
                    left: `${Math.random() * 100}%`,
                    top: `${Math.random() * 100}%`,
                    borderRadius: '50%',
                    pointerEvents: 'none'
                  }}
                />
              ))}
            </div>

            <div style={{ position: 'relative', zIndex: 10 }}>
              {/* Close Button */}
              <button 
                onClick={() => {
                  setShowMenu(false);
                  if (typeof document !== 'undefined') document.body.style.overflow = 'auto';
                }}
                style={{ 
                  position: 'fixed', 
                  top: '30px', 
                  right: '30px',
                  fontSize: '32px',
                  background: 'none',
                  border: 'none',
                  color: isDark ? '#fff' : '#000',
                  cursor: 'pointer',
                  zIndex: 20,
                  transition: 'all 0.3s ease'
                }}
                onMouseEnter={(e) => e.target.style.color = '#22C55E'}
                onMouseLeave={(e) => e.target.style.color = isDark ? '#fff' : '#000'}
              >
                ✕
              </button>

              <div className="max-w-7xl mx-auto px-6 md:px-12 py-24">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-20 md:gap-32">
                  {/* Available Products */}
                  <div>
                    <h2 className="text-4xl md:text-5xl font-semibold mb-16" style={{ letterSpacing: '3px', color: '#22C55E' }}>
                      AVAILABLE
                    </h2>
                    <div className="space-y-12">
                      {menuCategories.available.map((category, idx) => (
                        <div 
                          key={idx} 
                          onClick={() => {
                            setShowMenu(false);
                            if (typeof document !== 'undefined') document.body.style.overflow = 'auto';
                            // Navigate to products page with category filter
                            const categoryMap = {
                              0: 'standard',
                              1: '3d',
                              2: 'fitness',
                              3: 'leg'
                            };
                            setSelectedCategory(categoryMap[idx]);
                            setCurrentPage('products');
                            window.scrollTo(0, 0);
                          }}
                          className="cursor-pointer group transition-all duration-300"
                          style={{ borderLeft: '3px solid transparent', paddingLeft: '20px' }}
                          onMouseEnter={(e) => {
                            e.currentTarget.style.borderLeftColor = '#22C55E';
                            e.currentTarget.style.paddingLeft = '30px';
                          }}
                          onMouseLeave={(e) => {
                            e.currentTarget.style.borderLeftColor = 'transparent';
                            e.currentTarget.style.paddingLeft = '20px';
                          }}
                        >
                          <h3 className="text-xl md:text-2xl font-semibold mb-3 group-hover:text-green-400 transition-colors">
                            {category.name}
                          </h3>
                          <p className={`text-sm md:text-base ${isDark ? 'text-gray-400' : 'text-gray-600'} group-hover:text-gray-300 transition-colors`}>
                            {category.description}
                          </p>
                        </div>
                      ))}
                    </div>
                  </div>

                  {/* Coming Soon */}
                  <div>
                    <h2 className="text-4xl md:text-5xl font-semibold mb-16" style={{ letterSpacing: '3px', color: '#999' }}>
                      COMING SOON
                    </h2>
                    <div className="grid grid-cols-2 gap-8">
                      {menuCategories.comingSoon.map((category, idx) => (
                        <div 
                          key={idx}
                          className="opacity-70 cursor-default"
                        >
                          <h3 className="text-base md:text-lg font-semibold mb-3" style={{ color: isDark ? '#666' : '#999' }}>
                            {category.name}
                          </h3>
                          <p className={`text-xs md:text-sm ${isDark ? 'text-gray-600' : 'text-gray-500'}`}>
                            {category.description}
                          </p>
                        </div>
                      ))}
                    </div>
                  </div>
                </div>

                {/* Footer */}
                <div className="mt-24 md:mt-32 pt-16 border-t" style={{ borderColor: isDark ? 'rgba(34, 197, 94, 0.2)' : 'rgba(34, 197, 94, 0.3)' }}>
                  <p className={`text-xs md:text-sm font-mono ${isDark ? 'text-gray-500' : 'text-gray-600'}`}>
                    Premium quality sleeves crafted for performance and style | Explore our collections below
                  </p>
                </div>
              </div>
            </div>
          </div>
        </>
      )}

      {/* Category Pages - REMOVED, now using filtered products page */}

      {/* Products Listing Page */}
      {currentPage === 'products' && !selectedProduct && (
        <div className={`min-h-screen ${isDark ? 'bg-black' : 'bg-white'} pt-32 pb-20 px-4 md:px-8 relative z-20`} style={{ backgroundColor: '#0a0a0a', boxShadow: 'inset 0 0 60px rgba(34, 197, 94, 0.2)' }}>
          <div className="max-w-7xl mx-auto">
            {/* Category Header and Filter */}
            <div className="mb-12 md:mb-16">
              <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-6 mb-8">
                <div>
                  <h1 className="text-4xl md:text-6xl font-semibold mb-4">
                    {selectedCategory ? (
                      <>
                        {selectedCategory === 'standard' && 'Standard Arm Sleeves'}
                        {selectedCategory === '3d' && '3D Embroidered Fashion'}
                        {selectedCategory === 'fitness' && 'Fitness Arm Sleeves with Zips'}
                        {selectedCategory === 'leg' && 'Leg Stockings for Fitness'}
                      </>
                    ) : 'ALL PRODUCTS'}
                  </h1>
                  <p className={`text-lg ${isDark ? 'text-gray-400' : 'text-gray-600'}`}>
                    {filteredProducts.length} items
                  </p>
                </div>

                {selectedCategory && (
                  <button
                    onClick={() => {
                      setSelectedCategory(null);
                      window.scrollTo(0, 0);
                    }}
                    className="px-6 py-3 rounded-lg font-semibold transition-all"
                    style={{
                      background: '#22C55E',
                      color: 'black'
                    }}
                  >
                    View All
                  </button>
                )}
              </div>

              {/* Category Filters */}
              <div className="flex gap-3 flex-wrap">
                <button
                  onClick={() => {
                    setSelectedCategory(null);
                    window.scrollTo(0, 0);
                  }}
                  className="px-4 md:px-6 py-2 rounded-full text-sm font-semibold transition-all"
                  style={{
                    background: !selectedCategory ? '#22C55E' : isDark ? 'rgba(20, 20, 30, 0.6)' : 'rgba(240, 240, 240, 0.8)',
                    color: !selectedCategory ? 'black' : isDark ? '#fff' : '#000',
                    border: !selectedCategory ? 'none' : '1px solid rgba(34, 197, 94, 0.3)'
                  }}
                >
                  All
                </button>
                {['Standard', '3D Embroidered', 'Fitness', 'Leg Stockings'].map((cat, idx) => {
                  const catKey = ['standard', '3d', 'fitness', 'leg'][idx];
                  return (
                    <button
                      key={idx}
                      onClick={() => {
                        setSelectedCategory(catKey);
                        window.scrollTo(0, 0);
                      }}
                      className="px-4 md:px-6 py-2 rounded-full text-sm font-semibold transition-all"
                      style={{
                        background: selectedCategory === catKey ? '#22C55E' : isDark ? 'rgba(20, 20, 30, 0.6)' : 'rgba(240, 240, 240, 0.8)',
                        color: selectedCategory === catKey ? 'black' : isDark ? '#fff' : '#000',
                        border: selectedCategory === catKey ? 'none' : '1px solid rgba(34, 197, 94, 0.3)'
                      }}
                    >
                      {cat}
                    </button>
                  );
                })}
              </div>
            </div>

            {/* Products Grid */}
            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-3 md:gap-6">
              {filteredProducts.map((product) => (
                <div
                  key={product.id}
                  onClick={() => handleProductClick(product)}
                  className="cursor-pointer group overflow-hidden rounded-lg transition-all duration-300 hover:shadow-2xl"
                  style={{
                    background: isDark ? 'rgba(20, 20, 30, 0.6)' : 'rgba(240, 240, 240, 0.8)',
                    aspectRatio: '3/4',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    position: 'relative'
                  }}
                >
                  {product.image ? (
                    <img
                      src={process.env.PUBLIC_URL + '/' + product.image}
                      alt={product.name}
                      style={{
                        width: '100%',
                        height: '100%',
                        objectFit: 'contain',
                        transition: 'transform 0.3s ease'
                      }}
                      className="group-hover:scale-105"
                      onError={(e) => {
                        console.error('Image failed to load:', product.image);
                        e.target.style.display = 'none';
                      }}
                    />
                  ) : (
                    <div className="text-3xl md:text-5xl font-light text-center" style={{ color: isDark ? '#666' : '#999' }}>
                      {product.name.slice(0, 2)}
                    </div>
                  )}
                  <div className="absolute bottom-0 left-0 right-0 p-2 md:p-4 bg-gradient-to-t from-black/80 via-black/40 to-transparent translate-y-full group-hover:translate-y-0 transition-all duration-300">
                    <p className="text-white text-xs md:text-sm font-semibold truncate">{product.name}</p>
                    <p className="text-green-400 text-xs font-bold">${product.price}</p>
                  </div>
                </div>
              ))}
            </div>

            {filteredProducts.length === 0 && (
              <div className="text-center py-20">
                <p className={`text-lg ${isDark ? 'text-gray-400' : 'text-gray-600'}`}>
                  No products found in this category
                </p>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Cart Sidebar */}
      {showCart && (
        <div className={`fixed right-0 top-0 h-full w-full sm:w-96 ${isDark ? 'bg-gray-900' : 'bg-gray-50'} border-l ${isDark ? 'border-gray-800' : 'border-gray-200'} z-40 mt-16 overflow-y-auto`}>
          <div className="p-6">
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-xl font-semibold">Cart</h2>
              <button onClick={() => setShowCart(false)} className="p-1 hover:bg-gray-700 rounded">
                <X size={20} />
              </button>
            </div>
            {cart.length === 0 ? (
              <p className={isDark ? 'text-gray-400' : 'text-gray-600'}>Your cart is empty</p>
            ) : (
              <div className="space-y-4">
                {cart.map((item, idx) => (
                  <div key={idx} className={`pb-4 border-b ${isDark ? 'border-gray-800' : 'border-gray-200'}`}>
                    <p className="font-semibold text-sm">{item.name}</p>
                    <p className={isDark ? 'text-gray-400' : 'text-gray-600'}>${item.price}</p>
                    <button onClick={() => setCart(cart.filter((_, i) => i !== idx))} className="text-xs text-green-500 hover:text-green-400 mt-2">
                      Remove
                    </button>
                  </div>
                ))}
                <div className={`border-t ${isDark ? 'border-gray-800' : 'border-gray-200'} pt-4`}>
                  <p className="text-lg font-bold mb-4">Total: ${cart.reduce((sum, item) => sum + item.price, 0).toFixed(2)}</p>
                  <button className="w-full py-3 bg-green-500 text-black font-bold rounded-lg hover:bg-green-400 transition">
                    Checkout
                  </button>
                </div>
              </div>
            )}
          </div>
        </div>
      )}

      {/* OLD Products Section - REMOVED since we have dedicated page now */}

      {/* Product Detail Page */}
      {currentPage === 'product-detail' && selectedProduct && (
        <div className={`min-h-screen ${isDark ? 'bg-black' : 'bg-white'} pt-32 pb-20 px-4 md:px-8 relative z-20`}>
          <div className="max-w-6xl mx-auto">
            <button
              onClick={() => {
                setCurrentPage('products');
                setSelectedProduct(null);
              }}
              className="mb-12 text-sm font-semibold hover:opacity-70 transition"
              style={{ color: '#22C55E' }}
            >
              ← BACK TO PRODUCTS
            </button>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
              {/* Right side - Product Image/Preview - Shows FIRST on mobile */}
              <div className="flex items-center justify-center order-first md:order-last">
                <div
                  style={{
                    width: '100%',
                    height: '400px',
                    background: isDark ? 'rgba(20, 20, 30, 0.4)' : 'rgba(240, 240, 240, 0.6)',
                    borderRadius: '12px',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    border: `1px solid ${isDark ? 'rgba(34, 197, 94, 0.2)' : 'rgba(0, 0, 0, 0.1)'}`
                  }}
                >
                  {selectedProduct.image ? (
                    <img
                      src={process.env.PUBLIC_URL + '/' + selectedProduct.image}
                      alt={selectedProduct.name}
                      style={{
                        maxWidth: '100%',
                        maxHeight: '100%',
                        objectFit: 'contain'
                      }}
                      onError={(e) => {
                        console.error('Product image failed to load:', selectedProduct.image);
                        e.target.style.display = 'none';
                      }}
                    />
                  ) : (
                    <div className="text-6xl md:text-8xl font-light text-center" style={{ color: isDark ? '#333' : '#ddd' }}>
                      {selectedProduct.name.slice(0, 2)}
                    </div>
                  )}
                </div>
              </div>

              {/* Left side - Product Info */}
              <div className="order-last md:order-first">
                <h1 className="text-3xl md:text-5xl font-semibold mb-4">{selectedProduct.name}</h1>
                <p className="text-base md:text-lg font-semibold mb-8" style={{ color: '#22C55E' }}>${selectedProduct.price}</p>

                <div className="space-y-8 mb-12">
                  <div>
                    <p className="text-xs font-mono mb-4" style={{ color: '#22C55E', letterSpacing: '1px' }}>AVAILABLE COLORS</p>
                    <div className="flex gap-3 flex-wrap">
                      {selectedProduct.colors.map((color) => (
                        <span
                          key={color}
                          className="text-sm px-5 py-3 rounded-full font-semibold transition-all cursor-pointer hover:scale-110"
                          style={{
                            background: isDark ? 'rgba(255, 255, 255, 0.1)' : 'rgba(0, 0, 0, 0.05)',
                            color: isDark ? '#fff' : '#000',
                            border: '1px solid rgba(34, 197, 94, 0.3)'
                          }}
                        >
                          • {color}
                        </span>
                      ))}
                    </div>
                  </div>

                  <div>
                    <p className="text-xs font-mono mb-4" style={{ color: '#22C55E', letterSpacing: '1px' }}>SELECT SIZE</p>
                    <div className="flex gap-3 flex-wrap">
                      {['XS', 'S', 'M', 'L', 'XL'].map((size) => (
                        <span
                          key={size}
                          className="text-sm px-5 py-3 rounded-full font-semibold transition-all cursor-pointer hover:scale-110"
                          style={{
                            background: isDark ? 'rgba(255, 255, 255, 0.1)' : 'rgba(0, 0, 0, 0.05)',
                            color: isDark ? '#fff' : '#000',
                            border: '1px solid rgba(34, 197, 94, 0.3)'
                          }}
                        >
                          {size}
                        </span>
                      ))}
                    </div>
                  </div>

                  <div>
                    <p className="text-xs font-mono mb-2" style={{ color: '#22C55E' }}>DESCRIPTION</p>
                    <p className={`text-sm ${isDark ? 'text-gray-400' : 'text-gray-600'}`}>
                      Premium quality sleeve designed for the discerning customer. Each piece is carefully crafted with attention to detail and built to last.
                    </p>
                  </div>
                </div>

                <button
                  onClick={() => {
                    setCart([...cart, selectedProduct]);
                    setCurrentPage('products');
                    setSelectedProduct(null);
                  }}
                  className="w-full py-4 rounded-lg font-bold text-lg transition-all hover:opacity-90"
                  style={{
                    background: '#22C55E',
                    color: 'black'
                  }}
                >
                  ADD TO CART
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Main Content - Only show when NOT on product detail or products page */}
      {currentPage !== 'product-detail' && currentPage !== 'products' && (
        <>
          {/* Hero Section */}
          <section className="min-h-screen flex items-center justify-center relative pt-20 md:pt-0 section-appear" style={{ minHeight: '100vh', zIndex: 10, position: 'relative' }}>
            <div className="accent-dot" style={{ top: '10%', right: '10%', width: '30px', height: '30px', background: 'rgba(34, 197, 94, 0.2)', animationDelay: '0s', display: 'none' }} />
            <div className="accent-dot" style={{ bottom: '20%', left: '5%', width: '50px', height: '50px', background: 'rgba(34, 197, 94, 0.15)', animationDelay: '1s', display: 'none' }} />

            <div className="absolute inset-0 z-0"></div>
            <div className="relative z-20 w-full h-full flex flex-col justify-between p-6 md:p-16 max-w-7xl mx-auto">
              {/* Top Left - We are movement */}
              <div className="max-w-sm md:max-w-lg">
                <h1 className="text-3xl md:text-5xl lg:text-6xl font-semibold leading-tight mb-4 md:mb-6">
                  We are<br />movement
                </h1>
                <div className="w-12 h-1 bg-green-500 mb-4 md:mb-6"></div>
                <h2 className="text-base md:text-lg font-light mb-3 md:mb-4 tracking-wide">Your freedom to enjoy life</h2>
                <p className={`text-sm md:text-base leading-relaxed ${isDark ? 'text-gray-300' : 'text-gray-700'}`}>
                  Premium custom sleeves designed for the active mind.
                </p>
              </div>

              {/* Bottom Right - We are area boys */}
              <div className="max-w-sm md:max-w-lg self-end">
                <h1 className="text-3xl md:text-5xl lg:text-6xl font-semibold leading-tight mb-4 md:mb-6 text-right">
                  We are<br />area<br />boys
                </h1>
                <div className="w-12 h-1 bg-green-500 mb-4 md:mb-6 ml-auto"></div>
                <div className="text-right">
                  <button onClick={() => setCurrentPage('products')} className="px-4 md:px-6 py-2 md:py-3 border-2 border-green-500 text-green-500 font-bold hover:bg-green-500 hover:text-black transition duration-300 tracking-widest text-xs md:text-sm rounded">
                    START JOURNEY
                  </button>
                </div>
              </div>
            </div>
          </section>

      {/* Products Section - NOW MOVED TO DEDICATED PAGE, REMOVED FROM HOME */}

      {/* Products Collection on Home Page */}
      {currentPage !== 'product-detail' && currentPage !== 'products' && (
        <section 
          id="products-section"
          className={`min-h-screen py-16 md:py-32 px-4 md:px-8 section-appear ${isDark ? 'bg-black' : 'bg-white'}`} 
          style={{ position: 'relative', backgroundColor: '#0a0a0a', boxShadow: 'inset 0 0 60px rgba(34, 197, 94, 0.2)' }}
        >
          <div className="max-w-7xl mx-auto">
            <div className="mb-8 md:mb-12 flex justify-between items-center">
              <div>
                <h2 className="text-3xl md:text-4xl font-semibold mb-3" style={{ color: isDark ? '#fff' : '#000' }}>OUR COLLECTION</h2>
                <p className={`text-xs md:text-sm font-mono ${isDark ? 'text-gray-400' : 'text-gray-600'}`}>Explore our premium sleeves</p>
              </div>
              <button
                onClick={() => {
                  setSelectedCategory(null);
                  setCurrentPage('products');
                  window.scrollTo(0, 0);
                }}
                className="px-6 py-3 rounded-lg font-semibold transition-all hidden md:block"
                style={{
                  background: '#22C55E',
                  color: 'black'
                }}
              >
                VIEW ALL
              </button>
            </div>

            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-3 md:gap-6 mb-12">
              {products.slice(0, 8).map((product) => (
                <div
                  key={product.id}
                  onClick={() => handleProductClick(product)}
                  className="cursor-pointer group overflow-hidden rounded-lg transition-all duration-300 hover:shadow-2xl"
                  style={{
                    background: 'transparent',
                    aspectRatio: '3/4',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    position: 'relative'
                  }}
                >
                  {product.image ? (
                    <img
                      src={process.env.PUBLIC_URL + '/' + product.image}
                      alt={product.name}
                      style={{
                        width: '100%',
                        height: '100%',
                        objectFit: 'contain',
                        transition: 'transform 0.3s ease'
                      }}
                      className="group-hover:scale-105"
                      onError={(e) => {
                        console.error('Image failed to load:', product.image);
                        e.target.style.display = 'none';
                      }}
                    />
                  ) : (
                    <div className="text-3xl md:text-5xl font-light text-center" style={{ color: isDark ? '#666' : '#999' }}>
                      {product.name.slice(0, 2)}
                    </div>
                  )}
                  <div className="absolute bottom-0 left-0 right-0 p-2 md:p-4 bg-gradient-to-t from-black/80 via-black/40 to-transparent translate-y-full group-hover:translate-y-0 transition-all duration-300">
                    <p className="text-white text-xs md:text-sm font-semibold truncate">{product.name}</p>
                    <p className="text-green-400 text-xs font-bold">${product.price}</p>
                  </div>
                </div>
              ))}
            </div>

            {/* Mobile View All Button */}
            <button
              onClick={() => {
                setSelectedCategory(null);
                setCurrentPage('products');
                window.scrollTo(0, 0);
              }}
              className="w-full md:hidden px-6 py-3 rounded-lg font-semibold transition-all"
              style={{
                background: '#22C55E',
                color: 'black'
              }}
            >
              VIEW ALL PRODUCTS
            </button>
          </div>
        </section>
      )}
          <section 
            id="about-section"
            className={`min-h-screen py-16 md:py-32 px-4 md:px-8 section-appear ${isDark ? 'bg-black' : 'bg-white'}`} 
            style={{ position: 'relative', overflow: 'hidden' }}
          >
            <div style={{ position: 'absolute', inset: 0, zIndex: 0, overflow: 'hidden' }}>
              {[...Array(50)].map((_, i) => (
                <div
                  key={i}
                  style={{
                    position: 'absolute',
                    width: `${1 + Math.random() * 3}px`,
                    height: `${1 + Math.random() * 3}px`,
                    background: 'rgba(34, 197, 94, 0.8)',
                    left: `${Math.random() * 100}%`,
                    top: `${Math.random() * 100}%`,
                    borderRadius: '50%',
                    boxShadow: `0 0 ${5 + Math.random() * 10}px rgba(34, 197, 94, ${0.4 + Math.random() * 0.6})`,
                    animation: `twinkle ${2 + Math.random() * 4}s infinite`,
                    animationDelay: `${Math.random() * 2}s`
                  }}
                />
              ))}
            </div>

            <div className="max-w-6xl mx-auto relative z-10">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6 md:gap-16 items-center">
                {/* Left side - Logo */}
                <div style={{ position: 'relative', display: 'flex', alignItems: 'center', justifyContent: 'center', height: '300px', md: '500px' }}>
                  <img 
                    src={process.env.PUBLIC_URL + '/AB-removebg-preview.png'} 
                    alt="AREA BOYZ Logo" 
                    style={{
                      width: '280px',
                      height: '280px',
                      objectFit: 'contain',
                      filter: 'drop-shadow(0 0 20px rgba(34, 197, 94, 0.6))',
                      position: 'relative',
                      zIndex: 10
                    }}
                    onError={(e) => {
                      e.target.style.display = 'none';
                    }}
                  />
                </div>

                {/* Right side - About Us Info */}
                <div style={{
                  background: isDark ? 'rgba(20, 20, 30, 0.8)' : 'rgba(255, 255, 255, 0.8)',
                  border: '2px solid rgba(34, 197, 94, 0.3)',
                  borderRadius: '16px',
                  padding: '40px 30px',
                  backdropFilter: 'blur(10px)',
                  boxShadow: '0 8px 32px rgba(34, 197, 94, 0.1), inset 0 0 20px rgba(34, 197, 94, 0.05)',
                  position: 'relative',
                  overflow: 'hidden'
                }}>
                  {/* Top accent line */}
                  <div style={{ position: 'absolute', top: 0, left: 0, right: 0, height: '3px', background: 'linear-gradient(90deg, transparent, rgba(34, 197, 94, 0.8), transparent)' }} />

                  <div style={{ position: 'relative', zIndex: 2 }}>
                    <h2 className="text-3xl md:text-4xl font-semibold mb-3">ABOUT US</h2>
                    <p className="text-xs md:text-sm font-mono mb-6" style={{ color: '#22C55E', letterSpacing: '2px' }}>
                      THE STORY BEHIND AREA BOYZ
                    </p>

                    <div style={{ height: '3px', width: '60px', background: 'rgba(34, 197, 94, 0.6)', marginBottom: '24px' }} />

                    <p className={`text-sm md:text-base leading-relaxed mb-8 ${isDark ? 'text-gray-300' : 'text-gray-700'}`}>
                      We're a group of creative friends from Bangalore who share a passion for design and innovation. What started as a hobby became a mission to create something truly unique in the world of sleeve art.
                    </p>

                    <div className="space-y-6">
                      <div>
                        <p className="text-xs font-mono mb-2" style={{ color: '#22C55E', letterSpacing: '1px' }}>OUR MISSION</p>
                        <p className={`text-sm ${isDark ? 'text-gray-400' : 'text-gray-600'}`}>
                          To transform everyday sleeves into wearable art. We believe in pushing boundaries and creating products that tell a story.
                        </p>
                      </div>
                      <div>
                        <p className="text-xs font-mono mb-2" style={{ color: '#22C55E', letterSpacing: '1px' }}>OUR VALUES</p>
                        <p className={`text-sm ${isDark ? 'text-gray-400' : 'text-gray-600'}`}>
                          Quality, creativity, and authenticity guide every design decision we make.
                        </p>
                      </div>
                      <div>
                        <p className="text-xs font-mono mb-2" style={{ color: '#22C55E', letterSpacing: '1px' }}>BASED IN</p>
                        <p className={`text-sm ${isDark ? 'text-gray-400' : 'text-gray-600'}`}>
                          Bangalore, India 🇮🇳
                        </p>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </section>
        </>
      )}

      {/* Bottom Navigation */}
      <nav className={`fixed bottom-8 left-1/2 transform -translate-x-1/2 z-40`}>
        <div style={{
          display: 'flex',
          alignItems: 'center',
          gap: 'clamp(4px, 1vw, 8px)',
          padding: 'clamp(8px, 2vw, 10px) clamp(12px, 3vw, 16px)',
          background: isDark ? 'rgba(20, 20, 30, 0.4)' : 'rgba(255, 255, 255, 0.4)',
          backdropFilter: 'blur(20px)',
          border: `1px solid ${isDark ? 'rgba(34, 197, 94, 0.2)' : 'rgba(34, 197, 94, 0.3)'}`,
          borderRadius: '50px',
          boxShadow: '0 8px 32px rgba(34, 197, 94, 0.1)'
        }}>
          <button 
            onClick={() => {
              setCurrentPage('home');
              window.scrollTo(0, 0);
            }}
            className="rounded-full font-semibold transition-all hover:bg-white/10"
            style={{
              padding: 'clamp(6px, 1.5vw, 8px) clamp(10px, 2vw, 20px)',
              fontSize: 'clamp(10px, 2vw, 14px)'
            }}
          >
            Home
          </button>
          <button 
            onClick={() => {
              setSelectedCategory(null);
              setCurrentPage('products');
              window.scrollTo(0, 0);
            }}
            className="rounded-full font-semibold transition-all hover:bg-white/10"
            style={{
              padding: 'clamp(6px, 1.5vw, 8px) clamp(10px, 2vw, 20px)',
              fontSize: 'clamp(10px, 2vw, 14px)'
            }}
          >
            Products
          </button>
          <button 
            onClick={() => setShowCart(!showCart)}
            className="rounded-full font-semibold transition-all hover:bg-white/10 relative"
            style={{
              padding: 'clamp(6px, 1.5vw, 8px) clamp(10px, 2vw, 20px)',
              fontSize: 'clamp(10px, 2vw, 14px)'
            }}
          >
            Cart
            {cart.length > 0 && <span className="absolute -top-2 -right-2 w-4 h-4 rounded-full text-xs flex items-center justify-center" style={{ background: '#22C55E', color: isDark ? 'black' : 'white', fontSize: '10px' }}>{cart.length}</span>}
          </button>
          <button 
            onClick={() => setShowMenu(!showMenu)}
            className="rounded-full font-semibold transition-all hover:bg-white/10"
            style={{
              padding: 'clamp(6px, 1.5vw, 8px) clamp(10px, 2vw, 20px)',
              fontSize: 'clamp(10px, 2vw, 14px)'
            }}
          >
            Menu
          </button>
          
          {/* Divider */}
          <div style={{ height: '20px', width: '1px', background: 'rgba(34, 197, 94, 0.3)', margin: '0 clamp(4px, 1vw, 6px)' }} />
          
          {/* Dark Mode Toggle */}
          <button 
            onClick={() => setIsDark(!isDark)}
            className="rounded-full font-semibold transition-all"
            style={{ 
              background: '#22C55E', 
              color: isDark ? 'black' : 'white',
              padding: 'clamp(6px, 1.5vw, 8px) clamp(10px, 2vw, 20px)',
              fontSize: 'clamp(10px, 2vw, 14px)',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center'
            }}
          >
            {isDark ? <Sun size={16} /> : <Moon size={16} />}
          </button>
        </div>
      </nav>
    </div>
  );
}